// ---------- Voetbal IQ: Wat doe jij? ----------
IQ_QUIZ.push(
  {q:"Je hebt net getraind en je benen zijn stijf. Wat doe je?", options:["Meteen op de bank gaan liggen","5 minuten rekken: hamstring, bovenbeen, kuit en heup","Nog een uur voetballen"], answer:1, why:"Rekken na de training houdt je benen soepel en helpt je herstellen."},
  {q:"Je krijgt kramp in je kuit tijdens de wedstrijd. Wat doe je?", options:["Doorspelen","Je been strekken en je tenen naar je toe trekken","Gaan zitten en niets doen"], answer:1, why:"Door je kuit rustig te rekken, gaat de kramp het snelst weg."},
  {q:"Hoe lang houd je een rekoefening vast?", options:["2 seconden","20 tot 30 seconden","5 minuten"], answer:1, why:"20 tot 30 seconden is lang genoeg om je spier te laten ontspannen."},
  {q:"Moet een rekoefening pijn doen?", options:["Ja, hoe meer pijn hoe beter","Nee, je moet een fijne trek voelen","Maakt niet uit"], answer:1, why:"Pijn betekent dat je te ver gaat. Een rek moet fijn trekken."},
  {q:"Je team wint de bal. Wat is je eerste gedachte?", options:["Kan ik snel vooruit?","Even uitrusten","De bal wegschieten"], answer:0, why:"Na balwinst is de tegenstander nog niet klaar, dus kijk eerst of je snel kunt aanvallen."},
  {q:"Er staan al twee teamgenoten bij de bal. Wat doe jij?", options:["Er ook naartoe lopen","Op je plek blijven of een vrije plek zoeken","Gaan zitten"], answer:1, why:"Als iedereen naar de bal gaat, is de rest van het veld leeg."},
  {q:"De keeper komt uit bij jouw 1-tegen-1. Wat doe je?", options:["Hard recht op hem schieten","Om hem heen gaan of de bal over hem heen chippen","Stoppen"], answer:1, why:"Als de keeper uitkomt, is er ruimte om hem heen of over hem heen."},
  {q:"Er komt een voorzet van links. Waar ga jij als spits heen?", options:["Naar de eerste of tweede paal","Naar de middenlijn","Achter de goal"], answer:0, why:"Bij de palen ontstaan de meeste kansen bij een voorzet."},
  {q:"Je team neemt een hoekschop. Jij bent verdediger. Wat doe je?", options:["Allemaal naar voren","Achterblijven om een counter te stoppen","Naar de bank"], answer:1, why:"Iemand moet achterblijven zodat de tegenstander niet makkelijk kan counteren."},
  {q:"Je krijgt een hoge bal. Wat doe je eerst?", options:["Meteen rennen","Kijken waar hij valt","Wegkijken"], answer:1, why:"Eerst kijken waar de bal valt, dan sta je op de goede plek."},
  {q:"Je zit op de bank als wissel. Wat doe je?", options:["Op je telefoon kijken","Kijken naar de wedstrijd en je team aanmoedigen","Slapen"], answer:1, why:"Door te kijken leer je wat er gebeurt en ben je klaar als je erin komt."},
  {q:"Je komt in het veld als wissel. Wat doe je in de eerste minuten?", options:["Rustig beginnen","Meteen scherp zijn en je positie innemen","Aan de zijlijn blijven"], answer:1, why:"Een wissel moet meteen energie geven aan het team."},
  {q:"Je speelt een slechte pass. Wat doe je?", options:["Je hoofd laten hangen","Meteen helpen om de bal terug te winnen","Boos worden"], answer:1, why:"Na een fout direct werken laat zien dat je een teamspeler bent."},
  {q:"Je tegenstander is sneller dan jij. Hoe verdedig je?", options:["Heel dichtbij staan","Iets meer afstand houden zodat hij niet langs je kan sprinten","Weglopen"], answer:1, why:"Met iets meer afstand heb je tijd om te reageren op zijn snelheid."},
  {q:"Je hebt de bal en je hoort 'man!'. Wat doe je?", options:["Rustig blijven staan","Snel de bal kaatsen of afschermen","De bal oppakken"], answer:1, why:"'Man' betekent dat er iemand in je rug komt."},
  {q:"Het regent en het veld is glad. Wat is slim?", options:["Hoge ballen spelen","Lage, harde passes en voorzichtig met slidings","Niet meedoen"], answer:1, why:"Op een nat veld gaat de bal sneller over de grond en glij je makkelijk uit."},
  {q:"Het waait hard. Wat doe je met lange ballen?", options:["Juist meer lange ballen","Liever korte passes over de grond","Niet passen"], answer:1, why:"Wind maakt lange ballen onvoorspelbaar."},
  {q:"Je bent moe na een tweede training op een dag. Wat doe je thuis?", options:["Nog 30 minuten thuistraining","Eten, drinken, rekken en vroeg naar bed","Gamen tot laat"], answer:1, why:"Na twee trainingen is herstel het belangrijkst."},
  {q:"Waarom eet je binnen een uur na de training?", options:["Omdat het moet","Omdat je spieren dan snel kunnen herstellen","Om dik te worden"], answer:1, why:"Na de training nemen je spieren voeding goed op voor herstel."},
  {q:"Wat drink je het best tijdens de training?", options:["Water","Frisdrank","Energiedrank"], answer:0, why:"Water is het beste voor jonge sporters."},
  {q:"Je hebt zin om op te geven tijdens een zware training. Wat helpt?", options:["Stoppen","Tegen jezelf zeggen: nog één keer","Klagen"], answer:1, why:"Nog één keer volhouden maakt je mentaal sterker."},
  {q:"Waarom train je je zwakke voet?", options:["Dat hoeft niet","Zodat je met beide voeten kunt spelen en minder voorspelbaar bent","Alleen als de trainer kijkt"], answer:1, why:"Met twee voeten heb je meer mogelijkheden."},
  {q:"Je hebt de bal bij de zijlijn en een teamgenoot loopt achter je langs. Hoe heet dat?", options:["Overlap","Buitenspel","Een-twee"], answer:0, why:"Een overlap is als een teamgenoot achter je langs naar voren loopt."},
  {q:"Je staat met je rug naar het doel en krijgt de bal. Een verdediger staat dicht in je rug. Wat doe je?", options:["Draaien","Kaatsen naar een teamgenoot of afschermen","De bal laten liggen"], answer:1, why:"Met een verdediger dicht in je rug is draaien moeilijk. Kaatsen is slim."},
  {q:"Waarom moet je voor de training opwarmen?", options:["Om moe te worden","Om je spieren warm te maken en blessures te voorkomen","Dat hoeft niet"], answer:1, why:"Warme spieren werken beter en scheuren minder snel."},
  {q:"De tegenstander speelt met een hoge verdediging. Wat is een goed idee?", options:["Ballen in de ruimte achter de verdediging","Alleen terugspelen","Niets"], answer:0, why:"Achter een hoge verdediging is veel ruimte."},
  {q:"De tegenstander staat heel laag en compact. Wat werkt vaak?", options:["Snel de bal rondspelen en van kant wisselen","Altijd door het midden","Opgeven"], answer:0, why:"Door snel te wisselen van kant ontstaan er gaten in een laag blok."},
  {q:"Na een wedstrijd heb je overal spierpijn. Wat doe je de dag erna?", options:["Hard trainen","Rustig bewegen: wandelen, fietsen en rekken","Helemaal niet bewegen"], answer:1, why:"Rustig bewegen helpt je spieren sneller herstellen."},
  {q:"Je wilt beter worden in koppen. Wat oefen je?", options:["Met je ogen dicht koppen","Met je voorhoofd koppen en je ogen open houden","Met je kruin koppen"], answer:1, why:"Met je voorhoofd en ogen open kop je het best en het veiligst."},
  {q:"Wat doe je na een slechte wedstrijd?", options:["Een week niet meer voetballen","Eén leerpunt opschrijven en de volgende training er weer vol voor gaan","Je teamgenoten de schuld geven"], answer:1, why:"Van een slechte wedstrijd kun je leren. Daarna ga je weer door."}
);

// ---------- Dagles: techniek ----------
DAILY_LESSONS.push(
  L("Rekken na de training: de vaste vijf", "Na elke training rek je vijf plekken: hamstring, bovenbeen, kuit, lies en heup.", "Voetballers gebruiken deze spieren het meest. Soepele spieren raken minder snel geblesseerd.", ["Loop eerst 3 minuten rustig uit.","Rek elke spier 20 tot 30 seconden per kant.","Adem rustig en ga niet veren."], "Doe vandaag na je training of thuis de vaste vijf: halve split, bank-rek, achillespees-rek, brede lies-rek en knielende heupbuiger.", "Rekken met koude spieren of doorduwen als het pijn doet.", "Vijf plekken, dertig seconden, rustig ademen."),
  L("Aannemen met je hoofd", "Een bal uit de lucht kun je ook met je hoofd doodleggen.", "Soms is de bal te hoog voor je borst of voet.", ["Kijk naar de bal.","Raak hem met je voorhoofd en buig je nek iets mee naar achteren.","Laat de bal zacht voor je vallen."], "Gooi de bal 15 keer op en probeer hem met je hoofd zacht te laten vallen.", "Hard tegen de bal koppen in plaats van mee te geven.", "Meegeven, niet duwen."),
  L("De schaar", "De schaar is een schijnbeweging waarbij je met je voet om de bal heen draait.", "De verdediger denkt dat je naar de ene kant gaat, maar jij gaat de andere kant op.", ["Dribbel op de verdediger af.","Draai je voet van binnen naar buiten om de bal heen.","Neem de bal met de buitenkant van je andere voet mee."], "Doe 10 scharen bij een pion naar links en 10 naar rechts.", "De schaar te ver van de verdediger doen.", "Dichtbij, snel, andere kant op."),
  L("De step-over op snelheid", "Een step-over op snelheid is lastiger te verdedigen dan stilstaand.", "De verdediger moet tegelijk achteruit lopen en reageren.", ["Dribbel op snelheid.","Stap over de bal heen.","Ga met je andere voet weg naar de andere kant."], "Doe 10 keer een step-over in de loop.", "Stilstaan voor je de step-over doet.", "In de loop, niet stil."),
  L("De Marseille-draai", "Bij deze draai rol je de bal met je zool terwijl je om je as draait.", "Je beschermt de bal met je lichaam tijdens de draai.", ["Zet je zool op de bal en trek hem terug.","Draai je lichaam om.","Trek de bal met je andere zool mee."], "Oefen de draai langzaam 10 keer en dan 10 keer sneller.", "Te snel willen en de bal kwijtraken.", "Eerst langzaam, dan snel."),
  L("De elastico (beginnersversie)", "Met de buitenkant duw je de bal één kant op en met de binnenkant trek je hem terug.", "Een snelle richtingverandering die verdedigers verrast.", ["Duw de bal met de buitenkant naar buiten.","Draai je enkel snel om.","Trek de bal met de binnenkant terug."], "Doe 20 keer de beweging langzaam bij een pion.", "De bal te ver duwen met de buitenkant.", "Kort duwen, snel terug."),
  L("Een pass met de wreef over de grond", "Met je wreef kun je de bal hard over de grond spelen.", "Voor lange, snelle passes die niet stuiteren.", ["Wijs je tenen naar beneden.","Houd je knie boven de bal.","Raak de bal in het midden met je wreef."], "Speel 20 harde wreefpasses tegen een muur op 15 meter.", "Achterover leunen, waardoor de bal omhoog gaat.", "Tenen omlaag, knie over de bal."),
  L("Een pass met spin terug", "Met backspin stopt de bal sneller bij je teamgenoot.", "Handig voor korte, hoge ballen over een tegenstander.", ["Raak de bal helemaal onderaan.","Prik onder de bal.","Stop je voet na het raken."], "Probeer 15 keer een korte chip met backspin.", "Doorzwaaien, waardoor de bal te ver gaat.", "Onderaan prikken, voet stoppen."),
  L("Je lichaam laag bij duels", "Wie lager staat, staat steviger.", "Met een laag zwaartepunt word je minder makkelijk weggeduwd.", ["Buig je knieën.","Zet je voeten breed.","Houd je bovenlichaam iets naar voren."], "Oefen met een vriend schouderduels in een lage houding, 10 keer.", "Rechtop staan met je benen gestrekt.", "Laag en breed."),
  L("Een bal afschermen met je rug naar het doel", "Als spits krijg je vaak de bal met je rug naar het doel.", "Als je de bal kunt vasthouden, kan je team mee naar voren.", ["Zet je billen tegen de verdediger.","Houd je armen breed voor balans.","Neem de bal aan met de voet die het verst van de verdediger is."], "Oefen 10 keer: bal aannemen tegen de muur met iemand of een stoel in je rug.", "Rechtop staan, waardoor je makkelijk wordt weggeduwd.", "Billen erin, armen breed, verste voet."),
  L("Een snelle kaats", "Een kaats in één keer is de snelste manier om langs een tegenstander te komen.", "De tegenstander moet ineens twee spelers bijhouden.", ["Speel de bal naar je teamgenoot.","Sprint meteen langs de tegenstander.","Neem de bal in de loop terug."], "Speel 20 keer een-twee tegen de muur en sprint daarna.", "Na je pass blijven staan.", "Pass en gaan."),
  L("Een strakke lage voorzet op de eerste paal", "Een lage voorzet op de eerste paal is lastig voor de keeper.", "De aanvaller hoeft de bal maar aan te raken.", ["Kijk waar je aanvaller loopt.","Raak de bal met de binnenkant van je wreef.","Speel hard en laag naar de eerste paal."], "Speel 15 voorzetten naar een pion bij de eerste paal.", "Een hoge, zachte voorzet die de keeper makkelijk pakt.", "Laag, hard, eerste paal."),
  L("Een doelpunt met je hoofd", "Een kopbal op doel moet hard en naar beneden.", "Een stuiterende bal is het moeilijkst voor een keeper.", ["Kijk naar de bal.","Spring en raak hem met je voorhoofd.","Knik naar beneden richting doel."], "Gooi de bal 15 keer op en kop naar beneden op een doel.", "Met je ogen dicht koppen.", "Ogen open, naar beneden."),
  L("Wegdraaien van je tegenstander bij een aanname", "Met je eerste aanraking kun je meteen van je tegenstander wegdraaien.", "Zo win je tijd en ruimte.", ["Kijk waar de tegenstander staat.","Neem de bal aan naar de kant waar hij niet staat.","Draai met de bal mee."], "Oefen 20 aannames tegen de muur, steeds weg van een denkbeeldige tegenstander.", "De bal naar de tegenstander toe aannemen.", "Aanname weg van druk."),
  L("Een schot met je buitenkant", "Een schot met je buitenkant draait naar buiten weg.", "Verrassend voor de keeper.", ["Draai je enkel iets naar binnen.","Raak de bal met de buitenkant van je wreef.","Volg na in de richting van het doel."], "Schiet 15 keer met je buitenkant op een doel.", "De bal met je tenen raken.", "Buitenkant wreef, enkel strak."),
  L("Een pass door de lucht met de binnenkant", "Een korte hoge bal speel je met de binnenkant.", "Om over een tegenstander heen te spelen.", ["Leun iets achterover.","Raak de bal onderaan met je binnenkant.","Til je voet omhoog bij het raken."], "Speel 20 keer een korte hoge bal over een tas.", "Te hard, waardoor de bal te ver gaat.", "Onderaan raken, zacht optillen."),
  L("De keeper aankijken bij een penalty", "Kijk voor je aanloop naar de keeper, niet naar je hoek.", "Zo verraad je niet waar je heen schiet.", ["Kies je hoek in je hoofd.","Kijk de keeper aan.","Kijk bij het raken naar de bal."], "Neem 10 penalty's en kijk steeds eerst naar de keeper.", "Steeds naar je hoek kijken.", "Kies, kijk naar de keeper, schiet."),
  L("Snel opstaan na een duel", "Na een duel ben je pas klaar als je weer staat.", "Wie snel opstaat, kan de tweede bal winnen.", ["Rol op je zij.","Duw jezelf met één hand omhoog.","Kijk meteen naar de bal."], "Ga 10 keer op de grond liggen en sta zo snel mogelijk op.", "Blijven liggen.", "Opstaan en meedoen."),
  L("Kleine stappen voor je schot", "Met kleine stappen voor je schot zet je je standbeen precies goed.", "Een goed standbeen is de helft van een goed schot.", ["Neem grote stappen in je aanloop.","Maak de laatste twee stappen klein.","Zet je standbeen naast de bal."], "Schiet 15 keer en let op kleine laatste stapjes.", "Met een grote laatste stap te ver van de bal staan.", "Klein voor het schot."),
  L("Je armen bij sprinten", "Je armen helpen je sneller te sprinten.", "Je benen gaan net zo snel als je armen.", ["Buig je ellebogen 90 graden.","Zwaai van heup naar schouder.","Houd je schouders ontspannen."], "Doe 6 sprints van 20 meter en let alleen op je armen.", "Je armen voor je lichaam langs zwaaien.", "Armen recht naar voren en achteren."),
  L("Een pass naar de verre teamgenoot", "Een lange pass naar de andere kant verplaatst het spel in één keer.", "De tegenstander moet ver schuiven.", ["Kijk naar de verre kant.","Neem een schuine aanloop.","Raak onder het midden met je wreef."], "Speel 15 lange ballen naar een plek van 30 meter.", "Kijken naar de dichtstbijzijnde speler.", "Kijk ver, speel ver."),
  L("De bal laten stuiteren voor je aanname", "Soms is het beter om de bal eerst te laten stuiteren.", "Een stuiterende bal is soms makkelijker aan te nemen dan een hoge.", ["Kijk waar de bal valt.","Laat hem één keer stuiteren.","Neem hem aan op het hoogste punt van de stuit of net erna."], "Gooi de bal 20 keer hoog en neem aan na één stuit.", "Te vroeg naar de bal gaan.", "Laat hem stuiteren, neem hem rustig."),
  L("Afronden met de binnenkant in de verre hoek", "De verre hoek is het moeilijkst voor de keeper.", "De keeper moet het verst duiken.", ["Open je heup naar de verre hoek.","Raak de bal met de binnenkant.","Speel hem laag en strak."], "Schiet 20 keer in de verre hoek van een doel.", "Je heup dicht houden, waardoor de bal naar de korte hoek gaat.", "Heup open, verre hoek."),
  L("Een loopactie in de rug van de verdediger", "Loop in de rug van de verdediger als hij naar de bal kijkt.", "Hij ziet je dan niet aankomen.", ["Kijk wanneer de verdediger naar de bal kijkt.","Loop schuin achter hem langs.","Vraag de bal in de ruimte."], "Oefen in een partijtje 5 keer een loopactie in de rug.", "Recht voor de verdediger blijven staan.", "Zijn rug is jouw ruimte.")
);
